-- IqraSpace Learning — D1 (SQLite) schema.
--
-- Access control is NOT in the database: D1 has no row-level security, so
-- every read/write goes through the Worker API (worker/api), which applies
-- the per-role rules in worker/api/policies.js. Never expose this database
-- to anything but that Worker.
--
-- Type conventions:
--   uuid / text / date / time      -> TEXT  (uuids generated by the Worker)
--   timestamptz                    -> TEXT  ISO-8601 UTC, e.g. 2026-10-14T17:24:30.633Z
--   boolean                        -> INTEGER 0/1 (the API converts to true/false)
--   jsonb, text[], int[]           -> TEXT  JSON (the API parses/serialises)
-- Regex-style checks (slug format, Arabic script, https URLs) are enforced
-- by the Worker (worker/api/hooks.js).

-- ---------------------------------------------------------------- identity
CREATE TABLE users (
  id TEXT PRIMARY KEY,
  username TEXT NOT NULL UNIQUE,
  email TEXT UNIQUE,                 -- optional contact email
  phone TEXT,
  full_name TEXT NOT NULL,
  role TEXT NOT NULL CHECK (role IN ('tutor','student','guardian','admin','super_admin')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- Credentials and sessions are never reachable through the generic query API
-- (worker/api/schema.js does not list them).
CREATE TABLE user_credentials (
  user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  password_hash TEXT NOT NULL,       -- pbkdf2-sha256$<iterations>$<salt b64>$<hash b64>
  banned INTEGER NOT NULL DEFAULT 0 CHECK (banned IN (0,1)),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,       -- sha-256 of the bearer token; the token itself is never stored
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  expires_at TEXT NOT NULL
);
CREATE INDEX idx_sessions_user ON sessions(user_id);

-- Short-lived (1 hour, reusable) download tickets for lesson files.
CREATE TABLE file_tickets (
  token_hash TEXT PRIMARY KEY,
  path TEXT NOT NULL,
  expires_at TEXT NOT NULL
);

CREATE TABLE tutors (
  id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  bio TEXT,
  google_refresh_token_enc TEXT,
  default_lesson_duration_minutes INTEGER NOT NULL DEFAULT 20,
  default_reminder_minutes INTEGER NOT NULL DEFAULT 15,
  email_reminders_enabled INTEGER NOT NULL DEFAULT 1 CHECK (email_reminders_enabled IN (0,1)),
  lesson_start_reminders_enabled INTEGER NOT NULL DEFAULT 1 CHECK (lesson_start_reminders_enabled IN (0,1))
);

CREATE TABLE students (
  id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
  guardian_id TEXT REFERENCES users(id),
  date_of_birth TEXT
);

-- ---------------------------------------------------------------- classes
CREATE TABLE classes (
  id TEXT PRIMARY KEY,
  tutor_id TEXT NOT NULL REFERENCES tutors(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_classes_tutor ON classes(tutor_id);

CREATE TABLE class_members (
  id TEXT PRIMARY KEY,
  class_id TEXT NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
  student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  joined_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (class_id, student_id)
);
CREATE INDEX idx_class_members_class ON class_members(class_id);
CREATE INDEX idx_class_members_student ON class_members(student_id);

-- ---------------------------------------------------------------- lesson library
CREATE TABLE google_drive_files (
  id TEXT PRIMARY KEY,
  tutor_id TEXT NOT NULL REFERENCES tutors(id) ON DELETE CASCADE,
  drive_file_id TEXT NOT NULL,
  file_name TEXT NOT NULL,
  web_view_link TEXT,
  linked_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (tutor_id, drive_file_id)
);

CREATE TABLE lesson_plans (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  description TEXT,
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE lesson_plan_items (
  id TEXT PRIMARY KEY,
  lesson_plan_id TEXT NOT NULL REFERENCES lesson_plans(id) ON DELETE CASCADE,
  sequence INTEGER NOT NULL,
  title TEXT NOT NULL,
  objective TEXT,
  quran_surah_key TEXT,
  material_drive_file_id TEXT REFERENCES google_drive_files(id),
  material_storage_path TEXT,
  material_type TEXT DEFAULT 'pdf',
  material_page_start INTEGER,
  material_page_end INTEGER,
  prerequisite_item_id TEXT REFERENCES lesson_plan_items(id),
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (lesson_plan_id, sequence)
);
CREATE INDEX idx_lesson_plan_items_plan ON lesson_plan_items(lesson_plan_id, sequence);

CREATE TABLE class_lesson_plans (
  id TEXT PRIMARY KEY,
  class_id TEXT NOT NULL UNIQUE REFERENCES classes(id) ON DELETE CASCADE,
  lesson_plan_id TEXT NOT NULL REFERENCES lesson_plans(id) ON DELETE CASCADE,
  assigned_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_class_lesson_plans_plan ON class_lesson_plans(lesson_plan_id);

-- ---------------------------------------------------------------- scheduling & lessons
CREATE TABLE recurring_session_rules (
  id TEXT PRIMARY KEY,
  tutor_id TEXT NOT NULL REFERENCES tutors(id) ON DELETE CASCADE,
  student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  class_id TEXT NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
  days_of_week TEXT NOT NULL,        -- JSON int array, 0=Sunday .. 6=Saturday
  start_time TEXT NOT NULL,
  duration_minutes INTEGER NOT NULL DEFAULT 20,
  active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)),
  starts_on TEXT NOT NULL DEFAULT (date('now')),
  ends_on TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_recurring_rules_tutor ON recurring_session_rules(tutor_id);
CREATE INDEX idx_recurring_rules_student ON recurring_session_rules(student_id);

CREATE TABLE lessons (
  id TEXT PRIMARY KEY,
  class_id TEXT NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
  tutor_id TEXT NOT NULL REFERENCES tutors(id) ON DELETE CASCADE,
  student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  lesson_date TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'scheduled' CHECK (status IN ('scheduled','active','completed','cancelled')),
  start_time TEXT,
  duration_minutes INTEGER NOT NULL DEFAULT 45,
  quran_surah_key TEXT,
  lesson_plan_item_id TEXT REFERENCES lesson_plan_items(id),
  recurring_rule_id TEXT REFERENCES recurring_session_rules(id) ON DELETE SET NULL
);
CREATE INDEX idx_lessons_class_date ON lessons(class_id, lesson_date);
CREATE INDEX idx_lessons_student ON lessons(student_id);

CREATE TABLE lesson_materials (
  id TEXT PRIMARY KEY,
  lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  drive_file_id TEXT REFERENCES google_drive_files(id),
  storage_path TEXT,
  material_type TEXT DEFAULT 'pdf',
  page_start INTEGER,
  page_end INTEGER
);
CREATE INDEX idx_lesson_materials_lesson ON lesson_materials(lesson_id);

CREATE TABLE meetings (
  id TEXT PRIMARY KEY,
  lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  meet_url TEXT NOT NULL,
  scheduled_start TEXT,
  scheduled_end TEXT,
  calendar_event_id TEXT
);
CREATE INDEX idx_meetings_lesson ON meetings(lesson_id);

CREATE TABLE attendance (
  id TEXT PRIMARY KEY,
  lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  status TEXT NOT NULL CHECK (status IN ('present','absent','late','excused')),
  marked_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (lesson_id, student_id)
);
CREATE INDEX idx_attendance_student ON attendance(student_id);

CREATE TABLE lesson_progress (
  id TEXT PRIMARY KEY,
  lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  progress_note TEXT,
  surah_ayah_range TEXT,
  recitation_score INTEGER CHECK (recitation_score BETWEEN 0 AND 100),
  tajweed_score INTEGER CHECK (tajweed_score BETWEEN 0 AND 100),
  memorization_score INTEGER CHECK (memorization_score BETWEEN 0 AND 100),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_progress_student ON lesson_progress(student_id);

CREATE TABLE lesson_notes (
  id TEXT PRIMARY KEY,
  lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  note TEXT,
  covered TEXT,
  performance_note TEXT,
  next_lesson_plan TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE sharing_sessions (
  id TEXT PRIMARY KEY,
  lesson_id TEXT NOT NULL REFERENCES lessons(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','ended')),
  started_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  ended_at TEXT
);

CREATE TABLE highlighted_content (
  id TEXT PRIMARY KEY,
  sharing_session_id TEXT NOT NULL REFERENCES sharing_sessions(id) ON DELETE CASCADE,
  page_number INTEGER NOT NULL,
  highlight_type TEXT NOT NULL CHECK (highlight_type IN ('rect','text','ayah')),
  coordinates TEXT NOT NULL,         -- JSON {x,y,width,height}
  selected_text TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_highlight_session ON highlighted_content(sharing_session_id);

CREATE TABLE student_lesson_progress (
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  lesson_plan_id TEXT NOT NULL REFERENCES lesson_plans(id) ON DELETE CASCADE,
  current_item_id TEXT REFERENCES lesson_plan_items(id),
  status TEXT NOT NULL DEFAULT 'not_started'
    CHECK (status IN ('not_started','in_progress','needs_practice','completed','mastered')),
  tutor_confirmed INTEGER NOT NULL DEFAULT 0 CHECK (tutor_confirmed IN (0,1)),
  completed_at TEXT,
  notes TEXT,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (student_id, lesson_plan_id)
);
CREATE INDEX idx_student_lesson_progress_student ON student_lesson_progress(student_id);
CREATE INDEX idx_student_lesson_progress_plan ON student_lesson_progress(lesson_plan_id);

CREATE TABLE student_lesson_completions (
  id TEXT PRIMARY KEY,
  student_id TEXT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  lesson_plan_item_id TEXT NOT NULL REFERENCES lesson_plan_items(id) ON DELETE CASCADE,
  lesson_id TEXT REFERENCES lessons(id) ON DELETE SET NULL,
  confirmed_by TEXT NOT NULL REFERENCES users(id),
  completed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (student_id, lesson_plan_item_id)
);
CREATE INDEX idx_student_lesson_completions_student ON student_lesson_completions(student_id);

CREATE TABLE notifications (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  type TEXT NOT NULL,
  title TEXT NOT NULL,
  body TEXT,
  related_lesson_id TEXT REFERENCES lessons(id) ON DELETE SET NULL,
  read INTEGER NOT NULL DEFAULT 0 CHECK (read IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_notifications_user ON notifications(user_id, created_at DESC);

-- ---------------------------------------------------------------- duas (0025)
CREATE TABLE dua_categories (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL CHECK (length(trim(name)) > 0),
  name_ur TEXT,
  name_te TEXT,
  description TEXT NOT NULL DEFAULT '',
  description_ur TEXT,
  description_te TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0,1)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_by TEXT REFERENCES users(id) ON DELETE SET NULL,
  updated_by TEXT REFERENCES users(id) ON DELETE SET NULL
);

CREATE TABLE duas (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL CHECK (length(trim(title)) > 0),
  title_ur TEXT,
  arabic TEXT NOT NULL DEFAULT '',
  arabic_normalized TEXT NOT NULL DEFAULT '',   -- maintained by the Worker (normalizeArabic)
  transliteration_latin TEXT,
  transliteration_telugu TEXT,
  transliteration_urdu TEXT,
  translation_en TEXT,
  translation_ur TEXT,
  description TEXT,
  repeat_count INTEGER CONSTRAINT duas_repeat_count_check CHECK (repeat_count IS NULL OR repeat_count BETWEEN 1 AND 1000),
  source_type TEXT NOT NULL DEFAULT 'hadith' CHECK (source_type IN ('quran','hadith','mixed','other')),
  source_collection TEXT,
  source_reference TEXT,
  hadith_number TEXT,
  hadith_grade TEXT,
  quran_refs TEXT NOT NULL DEFAULT '[]',        -- JSON array
  audio_url TEXT,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','review','published','archived')),
  verification_status TEXT NOT NULL DEFAULT 'unchecked' CHECK (verification_status IN ('verified','unchecked','needs_review')),
  review_notes TEXT,
  origin TEXT NOT NULL DEFAULT 'iqs' CHECK (origin IN ('iqs','wyn_public_pdf','wyn_revised_edition','independent')),
  wyn_ids TEXT NOT NULL DEFAULT '[]',           -- JSON text array
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  published_at TEXT,
  created_by TEXT REFERENCES users(id) ON DELETE SET NULL,
  updated_by TEXT REFERENCES users(id) ON DELETE SET NULL,
  CONSTRAINT duas_arabic_required CHECK (status IN ('draft','archived') OR length(trim(arabic)) > 0),
  CONSTRAINT duas_published_needs_translation CHECK (status <> 'published' OR length(trim(coalesce(translation_en,''))) > 0)
);
CREATE INDEX duas_status_idx ON duas(status);
CREATE INDEX duas_arabic_normalized_idx ON duas(arabic_normalized);
CREATE INDEX duas_source_reference_idx ON duas(source_reference);

CREATE TABLE dua_category_map (
  dua_id TEXT NOT NULL REFERENCES duas(id) ON DELETE CASCADE,
  category_id TEXT NOT NULL REFERENCES dua_categories(id) ON DELETE RESTRICT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  context_title TEXT,
  context_title_ur TEXT,
  context_note TEXT,
  context_reference TEXT,
  context_repeat_count INTEGER CONSTRAINT dua_category_map_context_repeat_count_check
    CHECK (context_repeat_count IS NULL OR context_repeat_count BETWEEN 1 AND 1000),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  PRIMARY KEY (dua_id, category_id)
);
CREATE INDEX dua_category_map_category_idx ON dua_category_map(category_id, sort_order);

CREATE TABLE dua_audit_log (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  entity TEXT NOT NULL CHECK (entity IN ('dua','category','mapping')),
  entity_id TEXT NOT NULL,
  action TEXT NOT NULL CHECK (action IN ('insert','update','delete')),
  old_data TEXT,                     -- JSON
  new_data TEXT,                     -- JSON
  changed_fields TEXT NOT NULL DEFAULT '[]',  -- JSON text array
  changed_by TEXT,
  changed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX dua_audit_log_entity_idx ON dua_audit_log(entity, entity_id, changed_at DESC);
CREATE INDEX dua_audit_log_changed_at_idx ON dua_audit_log(changed_at DESC);
